{{{
    grid: { left: 72, right: 34, top: 70, bottom: 62, containLabel: true },
    tooltip: {
      trigger: "axis",
      valueFormatter: value => {
        const n = Number(value || 0);
        return Number.isInteger(n)
          ? n.toLocaleString()
          : n.toLocaleString(undefined, { maximumFractionDigits: 2 });
      }
    },
    xAxis: {
      axisLabel: {
        hideOverlap: true,
        rotate: 25,
        formatter: value => {
          const raw = String(value || "");
          if (/^\d{8}$/.test(raw)) return raw.slice(4, 6) + "/" + raw.slice(6, 8);
          return raw.replace("tutorial_step_", "Step ").replace("level_", "L");
        }
      }
    },
    yAxis: {
      axisLabel: {
        formatter: value => {
          const n = Number(value || 0);
          return Number.isInteger(n)
            ? n.toLocaleString()
            : n.toLocaleString(undefined, { maximumFractionDigits: 1 });
        }
      }
    },
    series: Array.from({ length: 8 }).map(() => ({
      symbolSize: 6,
      smooth: true,
      label: {
        show: false,
        position: "top",
        distance: 6,
        fontSize: 9,
        formatter: params => {
          const idx = params?.dataIndex ?? 0;
          const n = Number(params?.value?.[1] ?? params?.value ?? 0);
          if (!Number.isFinite(n) || n === 0) return "";
          const formatted = Number.isInteger(n)
            ? n.toLocaleString()
            : n.toLocaleString(undefined, { maximumFractionDigits: 2 });
          return idx === 0 || idx % 5 === 0 ? formatted : "";
        }
      },
      labelLayout: { hideOverlap: true }
    }))
  }}}

